import{Utils}from"../utils.min.js?v=1.0.0";let Base_Component={props:{featureData:{default:null},tierIndex:{default:1,type:Number},additionalTier:{type:Boolean,default:!1}},emits:["update"],data(){return{collapse:!1,condition_groups:[],id:Utils.generate_uuid()}},computed:{tier_no(){return this.tierIndex+1},feature_settings_data(){return JSON.parse(JSON.stringify(this.$data))},collapse_button_class(){return{"dashicons-arrow-up-alt2":this.collapse,"dashicons-arrow-down-alt2":!this.collapse}}},watch:{feature_settings_data:{deep:!0,handler(t){this.$emit("update",t)}}},mounted(){console.log(this.$data)},updated(){},methods:{add_condition_group(){Array.isArray(this.condition_groups)||(this.condition_groups=[]),this.condition_groups.push({id:Utils.generate_uuid()})},delete_condition_group(t){this.condition_groups.splice(t,1)}}};export default Base_Component;